def most_common_char(s):
    if not s:
        return None  # Handle empty string case
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    best_char = s[0]
    best_count = counts[s[0]]
    for ch in counts:  # Iterate over keys in counts instead of s
        if counts[ch] > best_count:
            best_char = ch
            best_count = counts[ch]
    return best_char
```

